def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    threat_bids = []
    soft_count = 0
    hard_count = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= DAILY_SALARY * 0.8 and opp.get('hp', 0) >= 6:
                    threat_bids.append(float(bid))
                if float(bid) <= 40:
                    soft_count += 1
                if float(bid) >= 90:
                    hard_count += 1

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.25))

    max_prev = max(prev_bids) if prev_bids else 0.0
    threat_prev = max(threat_bids) if threat_bids else max_prev

    supply_tight = supply <= 17
    supply_loose = supply >= 22

    urgency = 0
    if hp <= 3:
        urgency += 3
    elif hp <= 5:
        urgency += 2
    elif hp <= 7:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply_tight:
        urgency += 2
    elif supply_loose:
        urgency -= 1

    if hard_count >= 2:
        urgency += 1
    if soft_count >= 2:
        urgency -= 1

    days_left = 11 - day
    reserve_target = max(0.0, days_left * DAILY_SALARY * 0.38)
    spendable = max(0.0, budget - reserve_target)

    if urgency >= 6:
        base = max(95.0, threat_prev + 4.0, DAILY_SALARY * 1.15)
    elif urgency >= 4:
        base = max(72.0, threat_prev + 2.5, DAILY_SALARY * 0.92)
    elif urgency >= 2:
        base = max(48.0, min(threat_prev + 1.0, 88.0), DAILY_SALARY * 0.62)
    else:
        if supply_loose and hp >= 7:
            base = DAILY_SALARY * 0.28
        else:
            base = max(26.0, min(threat_prev * 0.72, 58.0), DAILY_SALARY * 0.4)

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget * 0.72)
    elif spendable > 0:
        base = min(base, spendable + DAILY_SALARY * 0.35)

    if hp <= 2 or no_water_days >= 2:
        base = max(base, min(budget, threat_prev + 5.0 if threat_prev > 0 else 90.0))

    bid = max(0.0, min(budget, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Basic sanity
    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    # If no one else is alive, conserve budget
    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    # Look only at yesterday's immediate behavior
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: fewer days of survival if supply is near minimum
    # (We don't know exact HP dynamics; use supply to set a conservative baseline.)
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Baseline bid: mid strategy to secure enough water share without draining budget.
    # If supply is lower, bid slightly more.
    base = DAILY_SALARY * (0.48 + 0.18 * (1.0 - supply_ratio))

    # If opponents were bidding extremely high yesterday, they were likely under pressure.
    # Increase only if our HP is low.
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        if hp <= 2.5 or no_water_days >= 2:
            bid = DAILY_SALARY * 0.75
        else:
            bid = base * 0.95
    elif highest_prev_bid >= DAILY_SALARY * 0.6:
        # Moderate pressure: small adjustment
        if hp <= 2.5:
            bid = DAILY_SALARY * 0.62
        else:
            bid = base
    else:
        # Low observed pressure: conserve
        if hp <= 2.5 or no_water_days >= 2:
            bid = DAILY_SALARY * 0.68
        else:
            bid = base * 0.88

    # Budget cap and safety
    bid = float(min(budget, bid))
    if bid < 0.0:
        bid = 0.0

    # Ensure we don't bid trivially when we must recover from no-water streak
    if no_water_days >= 3 and bid < DAILY_SALARY * 0.55:
        bid = float(min(budget, DAILY_SALARY * 0.7))

    return bid

